pub const ExprStore = struct {
    pub threadlocal var instance: ?*ExprStoreType = null;
    pub threadlocal var memory_allocator: ?*ASTMemoryAllocator = null;
    pub threadlocal var disable_reset: bool = false;

pub fn create() void {
            if (((instance != null) or (memory_allocator != null))) {
                return;
            }
            instance = ExprStoreType.init();
    }

pub fn reset() void {
            if ((disable_reset or (memory_allocator != null))) {
                return;
            }
            _ = instance.?.reset();
    }

pub fn deinit() void {
            if (((instance == null) or (memory_allocator != null))) {
                return;
            }
            _ = instance.?.deinit();
            instance = null;
    }

pub inline fn assert() void {
            if (comptime (Environment.isDebug or Environment.enable_asan)) {
                if (((instance == null) and (memory_allocator == null))) {
                    _ = bun.unreachablePanic("Store must be init'd", .{});
                }
            }
    }

pub fn begin() void {
            if ((memory_allocator != null)) {
                return;
            }
            if ((instance == null)) {
                _ = create();
                return;
            }
            if ((!disable_reset)) {
                _ = instance.?.reset();
            }
    }

pub fn append(comptime T: type, value: T) *T {
            if (memory_allocator) |allocator| {
                _ = &allocator;
                return allocator.append(T, value);
            }
            _ = Expr.Disabler.assert();
            return instance.?.append(T, value);
    }
};

