        }
        const r_string = r_opt.?;
        _ = l_string.resolveRopeIfNeeded(allocator);
        _ = r_string.resolveRopeIfNeeded(allocator);
        if ((l_string.isUTF8() != r_string.isUTF8())) {
            return null;
        }
        return .{ l_string, r_string };
}

