pub inline fn isPropertyAccess(client: *const Expr) bool {
        return client.hasValueForThisInCall();
}

pub inline fn isPrimitiveLiteral(client: *const Expr) bool {
        return std.meta.activeTag(client.data).isPrimitiveLiteral();
}

pub inline fn isRef(client: *const Expr, r: Ref) bool {
        return (switch (client.data) {
.e_import_identifier => |import_identifier| import_identifier.ref.eql(r),
.e_identifier => |ident| ident.ref.eql(r),
else => false,
});
}

pub fn isBoolean(a: *const Expr) bool {
        return (switch (a.data) {
.e_boolean, .e_branch_boolean => true,
.e_if => |ex| (ex.yes.isBoolean() and ex.no.isBoolean()),
.e_unary => |ex| ((ex.op == .un_not) or (ex.op == .un_delete)),
.e_binary => |ex| (switch (ex.op) {
.bin_strict_eq, .bin_strict_ne, .bin_loose_eq, .bin_loose_ne, .bin_lt, .bin_gt, .bin_le, .bin_ge, .bin_instanceof, .bin_in => true,
.bin_logical_or => (ex.left.isBoolean() and ex.right.isBoolean()),
.bin_logical_and => (ex.left.isBoolean() and ex.right.isBoolean()),
else => false,
}),
else => false,
});
}

pub fn assign(a: Expr, b: Expr) Expr {
        return init(E.Binary, E.Binary{ .op = .bin_assign, .left = a, .right = b }, a.loc);
}

pub inline fn at(expr: *const Expr, comptime Type: type, t: Type, _: std.mem.Allocator) Expr {
        return init(Type, t, expr.loc);
}

pub fn not(expr: *const Expr, allocator: std.mem.Allocator) Expr {
        return ((expr.maybeSimplifyNot(allocator)) orelse (Expr.init(E.Unary, E.Unary{ .op = .un_not, .value = expr.* }, expr.loc)));
}

pub inline fn hasValueForThisInCall(expr: *const Expr) bool {
        return (switch (expr.data) {
.e_dot, .e_index => true,
else => false,
});
}

pub fn maybeSimplifyNot(expr: *const Expr, allocator: std.mem.Allocator) ?Expr {
        switch (expr.data) {
.e_null, .e_undefined => {
return expr.at(E.Boolean, E.Boolean{ .value = true }, allocator);
},
.e_boolean, .e_branch_boolean => |b| {
return expr.at(E.Boolean, E.Boolean{ .value = (!(if (@typeInfo(@TypeOf(b)) == .@"enum") @intFromEnum(b) else b.value)) }, allocator);
},
.e_number => |n| {
return expr.at(E.Boolean, E.Boolean{ .value = (((if (@typeInfo(@TypeOf(n)) == .@"enum") @intFromEnum(n) else n.value) == 0) or std.math.isNan((if (@typeInfo(@TypeOf(n)) == .@"enum") @intFromEnum(n) else n.value))) }, allocator);
},
.e_big_int => |b| {
return expr.at(E.Boolean, E.Boolean{ .value = strings.eqlComptime((if (@typeInfo(@TypeOf(b)) == .@"enum") @intFromEnum(b) else b.value), "0") }, allocator);
},
.e_function, .e_arrow, .e_reg_exp => {
return expr.at(E.Boolean, E.Boolean{ .value = false }, allocator);
},
.e_unary => |un| {
if (((un.op == Op.Code.un_not) and ((if (@typeInfo(@TypeOf(un)) == .@"enum") @intFromEnum(un) else un.value).knownPrimitive() == .boolean))) {
            return (if (@typeInfo(@TypeOf(un)) == .@"enum") @intFromEnum(un) else un.value);
        }
},
.e_binary => |ex| {
switch (ex.op) {
.bin_loose_eq => {
ex.op = .bin_loose_ne;
        return expr.*;
},
.bin_loose_ne => {
ex.op = .bin_loose_eq;
        return expr.*;
},
.bin_strict_eq => {
ex.op = .bin_strict_ne;
        return expr.*;
},
.bin_strict_ne => {
ex.op = .bin_strict_eq;
        return expr.*;
},
.bin_comma => {
ex.right = ex.right.not(allocator);
        return expr.*;
},
else => {

},
}
},
.e_inlined_enum => |inlined| {
return (if (@typeInfo(@TypeOf(inlined)) == .@"enum") @intFromEnum(inlined) else inlined.value).maybeSimplifyNot(allocator);
},
else => {

},
}
        return null;
}

pub fn toStringExprWithoutSideEffects(expr: *const Expr, allocator: std.mem.Allocator) ?Expr {
        const unwrapped = expr.unwrapInlined();
        const slice = (switch (unwrapped.data) {
.e_null => "null",
.e_string => {
return expr.*;
},
.e_undefined => "undefined",
.e_boolean, .e_branch_boolean => |data| (if ((if (@typeInfo(@TypeOf(data)) == .@"enum") @intFromEnum(data) else data.value)) "true" else "false"),
.e_big_int => |bigint| (if (@typeInfo(@TypeOf(bigint)) == .@"enum") @intFromEnum(bigint) else bigint.value),
.e_number => |num| num.toString(allocator),
.e_reg_exp => |regexp| (if (@typeInfo(@TypeOf(regexp)) == .@"enum") @intFromEnum(regexp) else regexp.value),
.e_dot => |dot| @as(?[]const u8, brk: {
        if (bun.strings.eqlComptime((if (@typeInfo(@TypeOf(dot)) == .@"enum" or @typeInfo(@TypeOf(dot)) == .@"union") @tagName(dot) else dot.name), "constructor")) {
            break :brk (switch (dot.target.data) {
.e_string => "function String() { [native code] }",
.e_reg_exp => "function RegExp() { [native code] }",
else => null,
});
        }
        break :brk null;
}),
else => null,
});
        if (slice) |s| {
            _ = &s;
            return Expr.init(E.String, E.String.init(s), expr.loc);
        }
        return null;
}

pub fn StoredData(tag: Tag) type {
        const T = @FieldType(Data, tag);
        return (switch (@typeInfo(T)) {
.pointer => |ptr| ptr.child,
else => T,
});
}

pub fn stringToEquivalentNumberValue(str: []const u8) f64 {
        if ((str.len == 0)) {
            return 0;
        }
        if ((!bun.strings.isAllASCII(str))) {
            return std.math.nan(f64);
        }
        return bun.cpp.JSC__jsToNumber(str.ptr, str.len);
}
